 resume=last?'<section class="home-resume home-resume-featured" aria-label="Último canto abierto"><div><p>Último canto abierto</p><h2>'+E(last.title)+'</h2></div><button type="button" class="btn home-continue" data-score="'+E(last.id)+'" aria-label="Abrir de nuevo '+E(last.title)+'">Abrir ahora '+homeIcon('arrow')+'</button></section>':'';
 return '<div class="home-dashboard"><h1 class="visually-hidden">Inicio · Coro de demostración</h1>'  +rhSearch()+resume+quick+'<div class="home-columns">'+recentSection+'<div class="home-lists">' +listSection+ctNotices()+'</div></div></div>'
