function listCard(p){var n=S.items.filter(function(x){return x.playlist_id===p.id}).length;return '<div class="item"><div><div class="controls">'+(p.is_pinned?'<span class="badge pin">⌖ Fijada</span>':'')+'<span class="badge green">'+n+' partituras</span></div><h3>'+E(p.title)+'</h3><p>'+E(p.description||'Colección de partituras del coro')+'</p></div><div class="controls"><button class="btn white sm" data-openlist="'+E(p.id)+'">Abrir lista</button>'+(S.admin?'<button class="btn white sm" data-editlist="'+E(p.id)+'">Editar</button>':'')+'</div></div>'}
function lists(){var rows=S.playlists.slice().sort(function(a,b){return Number(b.is_pinned)-Number(a.is_pinned)||(a.sort_order||0)-(b.sort_order||0)});return pageHead('Listas y colecciones','Las listas publicadas son de consulta. Solo la administración puede crearlas o modificarlas.',S.admin?'<button class="btn" data-modal="playlist">＋ Nueva lista</button>':'')+(rows.length?'<div class="stack">'+rows.map(listCard).join('')+'</div>':empty('▤','Aún no hay listas publicadas','La administración podrá ordenar cantos para ensayos y eventos, y fijar listas para que siempre aparezcan primero.'))}
function playlistDetail(id,restoring){var p=S.playlists.find(function(x){return x.id===id});if(!p){notify('No se encuentra la lista');return}if(!restoring){routeSave();S.page='listadetail';routeList=id;routePush(null)}else{S.page='listadetail';routeList=id}backButton();by('currentTitle').textContent='Lista de cantos';var its=S.items.filter(function(x){return x.playlist_id===id}).sort(function(a,b){return a.position-b.position});by('screen').innerHTML=pageHead(p.title,p.description||'Lista de partituras','<div class="controls"><button class="btn white" data-page="listas">← Volver</button></div>')+(its.length?'<div class="song-list">'+its.map(function(x){var s=S.scores.find(function(y){return y.id===x.score_id});return s?songRow(s):''}).join('')+'</div>':empty('♫','Lista sin partituras','Esta lista todavía no contiene cantos.'))}
function itemCard(title,desc,badge,btn){return '<div class="item"><div>'+badge+'<h3>'+E(title)+'</h3><p>'+E(desc)+'</p></div>'+btn+'</div>'}
function renderContent(type){var info={eventos:['Agenda del coro','Ensayos, reuniones y presentaciones','events','starts_at'],avisos:['Comunicados','Avisos importantes para todos los integrantes','announcements','created_at'],uniformes:['Uniformes','Indicaciones de vestimenta para cada actividad','uniforms','event_at'],incidencias:['Registro de incidencias','Seguimiento de asuntos y necesidades del coro','incidents','created_at']},x=info[type],rows=S[x[2]],extra=(S.admin||(type==='incidencias'&&S.token))?'<button class="btn" data-modal="'+x[2]+'">＋ Nuevo registro</button>':'';if(type==='incidencias'&&!S.admin){rows=S.incidents}if(type==='incidencias'&&S.userId){rows=S.pending.map(function(x){return {category:x.body.category,description:x.body.description,status:'pendiente de sincronizar',created_at:new Date(x.saved_at).toISOString(),_pending:true}}).concat(rows)}return pageHead(x[0],x[1],extra)+(type==='incidencias'?'<div class="notice">Las incidencias pueden incluir asistencia, material, partituras, logística, uniformes, sonido y otros asuntos. Cada integrante puede ver sus propios reportes; el administrador tiene acceso al seguimiento general.</div>':'')+(rows.length?'<div class="stack">'+rows.map(function(r){var desc=r.description||r.body||r.instructions||r.category||'',date=r.starts_at||r.event_at||r.created_at;return itemCard(r.title||r.category||'Incidencia',desc+(date?' · '+fmt(date):''),'<span class="badge '+(r.status==='open'?'red':'green')+'">'+E(r.status||'Publicado')+'</span>',S.admin?'<button class="btn white sm" data-edit="'+E(x[2])+':'+E(r.id)+'">Editar</button>':'')}).join('')+'</div>':empty('◌','Sin información publicada','Los nuevos registros aparecerán aquí cuando sean creados por la administración.'))}
function accountForms(){if(S.accountMode==='login')return pageHead('Tu cuenta','Inicia sesión o crea una cuenta para guardar tus preferencias')+'<div class="card" style="max-width:490px"><form class="form" id="loginForm"><p>Accede con cualquier correo electrónico, como Outlook, Yahoo, iCloud o Gmail.</p><label>Correo electrónico<input type="email" name="email" required autocomplete="username"></label><label>Contraseña<input type="password" name="password" required autocomplete="current-password"></label><button class="btn" type="submit">Iniciar sesión</button></form><br><div class="controls">'+(S.registrationMode==='closed'?'':'<button class="link" data-account="signup">Crear cuenta con correo</button>')+'<button class="link" data-account="recover">¿Olvidaste tu contraseña?</button><button class="link" data-email-resend>Reenviar confirmación</button></div></div>';if(S.accountMode==='signup')return pageHead('Crear cuenta',S.registrationMode==='invitation'?'Solo por invitación':S.registrationMode==='approval'?'Registro con aprobación':'Registro abierto para integrantes del coro')+'<div class="card" style="max-width:490px"><form class="form" id="signupForm"><label>Correo electrónico<input type="email" name="email" required autocomplete="email"></label><label>Contraseña segura<input type="password" name="password" minlength="12" required autocomplete="new-password"></label><label>Confirmar contraseña<input type="password" name="confirm" minlength="12" required autocomplete="new-password"></label><p>Usa al menos 12 caracteres y una contraseña exclusiva. Si se requiere confirmación, revisa también el correo no deseado.</p><button class="btn" type="submit">Crear mi cuenta</button></form><br><button class="link" data-account="login">Ya tengo cuenta</button></div>';return pageHead('Recuperar contraseña','Enviaremos instrucciones a tu correo')+'<div class="card" style="max-width:490px"><form class="form" id="recoverForm"><label>Correo electrónico<input type="email" name="email" required></label><button class="btn" type="submit">Solicitar enlace de recuperación</button></form><br><button class="link" data-account="login">Volver a iniciar sesión</button></div>'}
function profilePane(){return '<div class="card" style="max-width:700px"><h3>Mi perfil musical</h3>'+(!S.profile?'<p>Completa tu nombre y tu cuerda para personalizar Estudio.</p>':'')+(!navigator.onLine?'<p>Perfil guardado en este dispositivo. Conéctate para modificarlo.</p>':'')+'<p>Cuenta: <strong>'+E(S.email||'Sesión iniciada')+'</strong></p><form class="form" id="profileForm"><label>Nombre visible<input name="display_name" maxlength="80" value="'+E(S.profile&&S.profile.display_name)+'" placeholder="Tu nombre"></label><label>Mi cuerda<select name="voice_part">'+[['sin_asignar','Todavía no conozco mi cuerda'],['soprano','Soprano'],['contralto','Contralto'],['tenor','Tenor'],['bajo','Bajo']].map(function(x){return '<option value="'+x[0]+'" '+(S.profile&&S.profile.voice_part===x[0]?'selected':'')+'>'+x[1]+'</option>'}).join('')+'</select></label><button class="btn" type="submit">Guardar mi perfil</button></form><br><div class="controls"><button class="btn white" data-account="change">Cambiar contraseña</button><button class="btn white" data-action="logout">Cerrar sesión</button></div></div>'}
function passwordPane(){return '<div class="card" style="max-width:520px"><h3>Cambiar contraseña</h3><form class="form" id="changePasswordForm"><label>Contraseña nueva<input name="password" type="password" minlength="12" required autocomplete="new-password"></label><label>Repetir contraseña<input name="confirm" type="password" minlength="12" required autocomplete="new-password"></label><button class="btn" type="submit">Actualizar contraseña</button></form><br><button class="link" data-account="profile">Volver al perfil</button></div>'}

function registerPanel(){var vals=[['open','Abierto a todos'],['approval','Con aprobación'],['invitation','Solo por invitación'],['closed','Registro cerrado']];var requests=S.joinRequests.filter(function(r){return r.status==='pending'});return '<div class="sec-head"><h2>Registro y permisos</h2></div><div class="two"><div class="card"><h3>Control de acceso</h3><form id="registrationForm" class="form"><label>Modo de registro<select name="mode">'+vals.map(function(v){return '<option value="'+v[0]+'"'+(v[0]===S.registrationMode?' selected':'')+'>'+v[1]+'</option>'}).join('')+'</select></label><button class="btn" type="submit">Guardar configuración</button></form><p>La restricción se comprueba en Supabase, no solo en la pantalla.</p></div><div class="card"><h3>Invitar por correo</h3><form id="invitationForm" class="form"><label>Correo que podrá registrarse<input type="email" name="email" required></label><button class="btn white" type="submit">Autorizar por 30 días</button></form><p>'+S.invites.length+' invitación(es) registradas. Comparte el enlace del sitio tú mismo.</p></div></div><div class="sec-head"><h2>Solicitudes de integrantes</h2></div>'+(requests.length?'<div class="study-list">'+requests.map(function(r){return '<div class="study-item"><div class="study-lesson"><strong>Solicitud '+E(r.user_id.slice(0,8))+'…</strong><div class="study-details">'+E(r.message||'Sin mensaje')+'</div></div><div class="study-item-actions"><button class="btn sm" data-member="yes:'+r.user_id+'">Aprobar</button><button class="btn white sm" data-member="no:'+r.user_id+'">Rechazar</button></div></div>'}).join('')+'</div>':'<div class="notice">No hay solicitudes pendientes.</div>')}
function joinPanel(){if(S.admin)return '<div class="notice"><strong>Director del Coro de demostración</strong> · Cuenta administrativa verificada</div>';if(S.memberOfRoma)return '<div class="notice">Miembro autorizado del Coro de demostración.</div>';if(S.joinRequests.some(function(r){return r.user_id===S.userId}))return '<div class="notice">Tu solicitud de ingreso al Coro de demostración está registrada.</div>';return '<div class="card" style="max-width:700px;margin-top:16px"><h3>Solicitar acceso al Coro de demostración</h3><p>Crear cuenta no te convierte automáticamente en integrante autorizado.</p><form class="form" id="joinCoroForm"><label>Mensaje al director<input name="message" maxlength="600" placeholder="Participo en los ensayos del coro"></label><button class="btn" type="submit">Enviar solicitud</button></form></div>'}
async function loadRegister(){if(!connected||!navigator.onLine)return;var owner=S.userId;try{var r=await req('choir_registration_settings','?id=eq.1&select=mode');S.registrationMode=r[0]&&r[0].mode||'open';var chor=await req('choirs','?slug=eq.roma&select=id');S.choirId=chor[0]&&chor[0].id;if(S.token&&S.userId&&S.choirId){var rs=await Promise.allSettled([req('choir_memberships','?choir_id=eq.'+S.choirId+'&user_id=eq.'+S.userId+'&select=status'),req('choir_join_requests','?choir_id=eq.'+S.choirId+(S.admin?'':'&user_id=eq.'+S.userId)+'&select=*')]);if(owner!==S.userId)return;S.memberOfRoma=rs[0].status==='fulfilled'&&rs[0].value.some(function(x){return x.status==='active'});S.joinRequests=rs[1].status==='fulfilled'?rs[1].value:[];if(S.admin){var invites=await req('choir_registration_invites','?select=*');if(owner===S.userId&&S.admin)S.invites=invites}}else{S.invites=[];S.joinRequests=[];S.memberOfRoma=false}}catch(err){console.warn('Accesos:',err.message)}}
async function submitRegister(e){e.preventDefault();if(!S.admin)return;try{var mode=new FormData(e.target).get('mode');await req('choir_registration_settings','?id=eq.1','PATCH',{mode:mode,updated_at:new Date().toISOString()});S.registrationMode=mode;render();notify('Modo actualizado a '+mode)}catch(err){notify(err.message)}}
async function submitInvite(e){e.preventDefault();if(!S.admin)return;try{var email=String(new FormData(e.target).get('email')).toLowerCase().trim();await req('choir_registration_invites','','POST',{email:email,expires_at:new Date(Date.now()+30*86400000).toISOString()});await loadRegister();render();notify('Correo autorizado')}catch(err){notify(err.message)}}
async function submitJoin(e){e.preventDefault();if(!S.token||!S.userId||!S.choirId)return;try{await req('choir_join_requests','','POST',{choir_id:S.choirId,user_id:S.userId,message:String(new FormData(e.target).get('message')||'').slice(0,600),status:'pending'});await loadRegister();render();notify('Solicitud enviada al director')}catch(err){notify(err.message)}}
async function approveJoin(id,allowed){if(!S.admin)return;try{var r=await fetch(C.url.replace(/\/$/,'')+'/rest/v1/rpc/approve_choir_member',{method:'POST',headers:authHeaders(true),body:JSON.stringify({p_choir_id:S.choirId,p_user_id:id,p_approve:allowed})});if(!r.ok)throw Error((await r.text()).slice(0,180));await loadRegister();render();notify(allowed?'Integrante aprobado':'Solicitud rechazada')}catch(err){notify(err.message)}}

function admin(){if(!connected)return pageHead('Tu cuenta','La base de datos no está disponible')+'<div class="notice danger" role="alert">El acceso requiere conexión al servicio de autenticación.</div><button class="btn" type="button" data-ct-retry>Reintentar conexión</button>';if(!S.token)return accountForms();if(S.accountMode==='change')return pageHead('Seguridad de la cuenta','Protege tu acceso con una contraseña robusta')+passwordPane();var welcome=pageHead(S.admin?'Administración del coro':'Mi cuenta','Sesión de '+S.email);if(!S.admin)return welcome+profilePane()+joinPanel();return welcome+'<div class="card"><h3>Dirección musical</h3><p>Tonos rápidos SATB sin conexión y generación MIDI completa.</p><button class="btn" data-director="launch">Abrir herramientas del director</button></div><div class="sec-head"><h2>Administración del coro</h2></div><div class="notice"><strong>Administración protegida.</strong> Supabase valida las escrituras en el servidor. Una sesión de miembro no permite publicar repertorios.</div><div class="tiles">'+[['Partituras','scores','score'],['Listas','playlists','playlist'],['Agenda','events','events'],['Comunicados','announcements','announcements']].map(function(x){return '<div class="tile"><small>'+x[0]+'</small><strong>'+S[x[1]].length+'</strong><button class="link" data-modal="'+x[2]+'">＋ Administrar</button></div>'}).join('')+'</div><div class="sec-head"><h2>Gestión del coro</h2></div><div class="two"><div class="card"><h3>Repertorio PDF</h3><p>Las 528 referencias iniciales ya están registradas en Supabase. Puedes subir partituras adicionales desde Repertorio.</p><br><button class="btn sm" data-page="repertorio">Abrir repertorio</button></div><div class="card"><h3>Uniformes e incidencias</h3><p>Organiza uniformes, materiales y reportes de los integrantes.</p><br><div class="controls"><button class="btn white sm" data-modal="uniforms">Uniformes</button><button class="btn white sm" data-modal="incidents">Incidencias</button></div></div></div>'+registerPanel()}

function more(){return pageHead('Más opciones','Accede a todas las áreas del coro desde el móvil.')+'<div class="two">'+[['eventos','Agenda','Ensayos y presentaciones'],['listas','Colecciones','Listas publicadas'],['avisos','Comunicados','Avisos y noticias'],['uniformes','Uniformes','Indicaciones de vestimenta'],['incidencias','Incidencias','Reportes y seguimiento'],['admin','Cuenta','Registro e inicio de sesión'],['repertorio','Sin conexión','Disponibilidad del repertorio']].map(function(x){return '<button class="card clickable" style="text-align:left;border:1px solid #e6ebf0" data-page="'+x[0]+'"><h3>'+E(x[1])+' →</h3><p>'+E(x[2])+'</p></button>'}).join('')+'</div>'}
function render(){var logged=!connected||!!S.userId,onboard=rhNeedsProfile()&&S.accountMode!=='change';if(S.page!=='estudio'&&window.CoroDirector&&CoroDirector.isOpen())CoroDirector.leave();document.body.classList.toggle('rh-auth',!logged);document.body.classList.toggle('rh-onboard',onboard);if(!logged){if(!navigator.onLine&&S.accountMode==='login'){by('screen').innerHTML=rhIntro('Roma Hub Demo','Conéctate a internet para iniciar sesión por primera vez.')+accountForms();return}by('screen').innerHTML=rhIntro('Roma Hub Demo','Tu música. Tu voz. Tu coro.')+accountForms();return}if(onboard){by('screen').innerHTML=rhIntro('Configura tu voz','Este paso se realiza una sola vez por cuenta.')+profilePane().replace('name="display_name"','name="display_name" required').replace('Guardar mi perfil','Continuar');return}if(S.page!=='repertorio')S.filtersOpen=false;nav();backButton();if(S.page==='listadetail'&&routeList){if(S.playlists.some(function(x){return x.id===routeList})){playlistDetail(routeList,true);if(window.CoroAuto)syncLibrary();return}S.page='listas';routeList=null;}var f={inicio:home,repertorio:repertorio,listas:lists,mas:rhChoir,estudio:CoroStudy.renderStudy,roma:CoroStudy.renderRoma,eventos:function(){return renderContent('eventos')},avisos:function(){return renderContent('avisos')},uniformes:function(){return renderContent('uniformes')},incidencias:function(){return renderContent('incidencias')},admin:rhAccount,directorpanel:function(){return S.admin?admin():rhAccount()}};by('screen').innerHTML=(f[S.page]||home)();if(window.CoroAuto)syncLibrary()}
var routeList=null,routeRestoring=false,readerEpoch=0,routeBusy=false;
var sharedStudyPending=false;
function routeState(overlay){return {coro:true,page:S.page,list:routeList,tab:S.tab,query:S.query,lang:S.lang,scroll:window.scrollY||0,overlay:overlay||null}}
function routeURL(st){var u=new URL(location.href);u.searchParams.delete('view');if(st.page!=='inicio')u.searchParams.set('view',st.page==='listadetail'?'listas':st.page);if(st.page==='listadetail'&&st.list)u.searchParams.set('list',st.list);else u.searchParams.delete('list');return u.pathname+u.search+u.hash}
function routePush(overlay){if(routeRestoring)return;var st=routeState(overlay);history.pushState(st,'',routeURL(st))}
function routeSave(){var st=history.state;if(st&&st.coro&&!st.overlay)history.replaceState(routeState(null),'',routeURL(routeState(null)))}
function backButton(){var b=by('coroBack');if(!b){b=document.createElement('button');b.id='coroBack';b.type='button';b.className='round';b.style.flexShrink='0';b.setAttribute('aria-label','Volver a la pantalla anterior');b.title='Volver';b.textContent='←';b.onclick=routeBack;var tools=document.querySelector('.topbar .tools');if(tools)tools.insertBefore(b,tools.firstChild)}b.hidden=S.page==='inicio';b.style.display=S.page==='inicio'?'none':''}
function closeReader(){if(S.doc&&S.reader)recordRecent();readerEpoch++;CoroStudy.cleanupPlayback();stopPdfReader();if(document.fullscreenElement&&document.exitFullscreen)document.exitFullscreen().catch(function(){});if(S.doc&&S.doc.destroy)try{S.doc.destroy()}catch(e){}by('readerRoot').innerHTML='';document.body.style.overflow='';S.doc=null;S.reader=null;if(S.page==='inicio'&&by('screen'))by('screen').innerHTML=home();if(window.CoroAuto&&CoroAuto.resumeAfterReader)CoroAuto.resumeAfterReader();if(syncRenderPending)setTimeout(safeSyncRender,0)}
function routeBack(){if(routeBusy)return;var st=history.state;if(st&&st.coro&&(st.overlay||S.page!=='inicio')){routeBusy=true;history.back();setTimeout(function(){routeBusy=false},700)}else if(by('readerRoot').children.length){closeReader()}else if(by('modalRoot').children.length){by('modalRoot').innerHTML=''}else if(S.page!=='inicio'){go('inicio')}}
function go(page){if(!P.some(function(x){return x[0]===page}))return;if(S.page===page&&!routeList){S.displayLimit=80;render();return}routeSave();S.page=page;routeList=null;S.displayLimit=80;routePush(null);window.scrollTo(0,0);render()}
function initRoutes(){var u=new URL(location.href),p=u.searchParams.get('view'),list=u.searchParams.get('list');sharedStudyPending=u.searchParams.get('study');if(['handel-hallelujah'].indexOf(sharedStudyPending)<0)sharedStudyPending=null;if(sharedStudyPending)p='estudio';if(!P.some(function(x){return x[0]===p}))p='inicio';if(history.state&&history.state.coro&&p!=='admin'){var old=history.state;S.page=sharedStudyPending?'estudio':old.page==='listadetail'?'listas':old.page;routeList=null;history.replaceState(routeState(null),'',routeURL(routeState(null)))}else{S.page='inicio';history.replaceState(routeState(null),'',routeURL(routeState(null)));if(p!=='inicio'){S.page=p;routePush(null)}}window.addEventListener('popstate',function(e){routeBusy=false;var st=e.state;if(!st||!st.coro)st={page:'inicio'};var old=S.page,oldList=routeList;routeRestoring=true;try{if(by('readerRoot').children.length)closeReader();if(by('modalRoot').children.length)by('modalRoot').innerHTML='';S.page=st.page||'inicio';routeList=st.list||null;S.tab=st.tab||'all';S.query=st.query||'';S.lang=st.lang||'all';if(old!==S.page||oldList!==routeList||!by('screen').children.length)render();backButton();if(st.overlay){history.replaceState(routeState(null),'',routeURL(routeState(null)))}requestAnimationFrame(function(){window.scrollTo(0,st.scroll||0)})}finally{routeRestoring=false}});
var obs=new MutationObserver(function(){if(routeRestoring)return;var st=history.state;if(by('readerRoot').children.length&&(!st||st.overlay!=='reader')){routeSave();routePush('reader')}else if(by('modalRoot').children.length&&(!st||!st.overlay)){routeSave();routePush('modal')}else if(st&&st.overlay==='modal'&&!by('modalRoot').children.length&&!by('readerRoot').children.length&&!routeBusy){routeBack()}});obs.observe(by('readerRoot'),{childList:true});obs.observe(by('modalRoot'),{childList:true});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&(by('readerRoot').children.length||by('modalRoot').children.length)){e.preventDefault();routeBack()}})}
