async function authSignup(e){e.preventDefault();var fd=new FormData(e.target),password=fd.get('password');if(password!==fd.get('confirm')){notify('Las contraseñas no coinciden');return}if(password.length<12){notify('Utiliza al menos 12 caracteres');return}try{var r=await fetch(C.url.replace(/\/$/,'')+'/auth/v1/signup?redirect_to='+encodeURIComponent(CoroAuthRedirect()),{method:'POST',headers:{apikey:C.key,'Content-Type':'application/json'},body:JSON.stringify({email:String(fd.get('email')||'').trim(),password:password})});var d=await r.json();if(!r.ok)throw Error(d.msg||d.error_description||d.message||'No se pudo crear la cuenta');if(d.access_token&&d.refresh_token){CoroSession.write(d);adoptSession(d);S.accountMode='profile';S.page='inicio';await loadProfile();render();foregroundSync();notify('Cuenta creada. Completa tu perfil musical.');return}S.accountMode='login';render();var emailField=document.querySelector('#loginForm input[name=email]');if(emailField)emailField.value=String(fd.get('email')||'').trim();notify('Revisa tu correo y confirma tu cuenta antes de iniciar sesión.')}catch(err){notify('Registro: '+err.message)}}
