async function acceptResetLink(){var hash=new URLSearchParams(location.hash.replace(/^#/,'')),type=hash.get('type'),access=hash.get('access_token'),refresh=hash.get('refresh_token');if(!access)return;if(['signup','email','recovery'].indexOf(type)<0||!refresh){history.replaceState(null,'',location.pathname+'?view=admin');notify('Enlace de acceso no válido.');return}history.replaceState(null,'',location.pathname+(type==='recovery'?'?view=admin':''));try{var r=await fetch(C.url.replace(/\/$/,'')+'/auth/v1/user',{headers:{apikey:C.key,Authorization:'Bearer '+access},cache:'no-store'});if(!r.ok)throw Error('Enlace vencido o inválido. Solicita uno nuevo.');var user=await r.json();if(!user.id||user.id!==tokenClaims(access).sub)throw Error('No se pudo verificar la cuenta.');var session={access_token:access,refresh_token:refresh};CoroSession.write(session);adoptSession(session);S.accountMode=type==='recovery'?'change':'profile';if(type==='recovery')S.page='admin';else S.page='inicio';notify(type==='recovery'?'Elige una nueva contraseña.':'Correo confirmado. Bienvenido a Roma Hub Demo.')}catch(e){notify(e.message||'No se pudo confirmar el correo.')}}
