async function login(e){e.preventDefault();if(!connected||navigator.onLine===false){notify('Necesitas conexión para iniciar sesión.');return}var fd=new FormData(e.target);try{var r=await fetch(C.url.replace(/\/$/,'')+'/auth/v1/token?grant_type=password',{method:'POST',headers:{'apikey':C.key,'Content-Type':'application/json'},body:JSON.stringify({email:String(fd.get('email')||'').trim(),password:fd.get('password')})});var a=await r.json();if(!r.ok||!a.access_token||!a.refresh_token)throw Error((a.error_code||a.code)==='email_not_confirmed'?'Confirma tu correo antes de acceder. Puedes reenviar la confirmación.':(a.error_code||a.code)==='invalid_credentials'?'Correo o contraseña incorrectos.':a.msg||a.error_description||a.message||'No se pudo iniciar sesión');CoroSession.write(a);adoptSession(a);S.accountMode='profile';S.page=sharedStudyPending?'estudio':'inicio';render();await loadProfile();render();await loadLocal();await loadRemote();await CoroStudy.load();await loadRegister();await syncPending();await syncFavorites();notify('Sesión iniciada');render()}catch(err){notify(err.message)}}function tokenClaims(token){try{var b=token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/');return JSON.parse(atob(b))}catch(_){return {}}}
function decodeUser(){var p=tokenClaims(S.token);S.admin=!!(p.app_metadata&&p.app_metadata.choir_role==='admin'&&p.exp>Date.now()/1000);S.email=p.email||'';S.userId=p.sub||'';if(!S.userId)S.token=''}
function resetAccountData(){rhProfileKnown=false;roleRefreshUser='';S.profile=null;S.memberOfRoma=false;S.invites=[];S.joinRequests=[];S.incidents=[];S.favorites=[];S.recent=[];S.pending=[];S.notes=[];S.scores=S.base.slice();S.playlists=[];S.items=[];S.events=[];S.announcements=[];S.uniforms=[];profileRevision++}
function adoptSession(a){var old=S.userId,newId=tokenClaims(a.access_token||'').sub||'';if(old!==newId){if(old){if(window.CoroAuto){CoroAuto.pauseForReader();CoroAuto.configure([],[])}if(by('readerRoot').children.length)closeReader();by('modalRoot').innerHTML='';CoroStudy.onLogout(old)}resetAccountData()}S.token=a.access_token||'';S.refreshToken=a.refresh_token||'';decodeUser();if(old!==S.userId){S.accountMode=S.userId?'profile':'login';restoreProfile();loadLocal().then(safeSyncRender)}}
function clearAuth(){var old=S.userId;if(old)try{localStorage.removeItem(profileKey(old))}catch(_){}CoroSession.clear();adoptSession({})}
