async function refreshSession(){if(!connected)return;var shared=CoroSession.read();if((shared.access_token||'')!==S.token||(shared.refresh_token||'')!==S.refreshToken)adoptSession(shared);if(!S.refreshToken||!navigator.onLine){decodeUser();return}var p=tokenClaims(S.token);if(p.exp>Date.now()/1000+120&&roleRefreshUser===S.userId)return;var original=S.refreshToken;try{var r=await fetch(C.url.replace(/\/$/,'')+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:C.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:original})});var a=await r.json();var latest=CoroSession.read();if(latest.refresh_token!==original||S.refreshToken!==original){adoptSession(latest);return}if(!r.ok){if((r.status===400||r.status===401)&&['refresh_token_not_found','refresh_token_already_used','session_not_found','session_expired','user_not_found'].indexOf(a.error_code||a.code)>=0){clearAuth();notify('Tu sesión terminó. Vuelve a iniciar sesión.')}return}if(!a.access_token||!a.refresh_token)return;CoroSession.write(a);adoptSession(a);roleRefreshUser=S.userId}catch(e){console.warn('Renovación temporalmente no disponible',e.message)}finally{decodeUser()}}

async function loadRemote(){if(!connected)return;var owner=S.userId,rows=await Promise.allSettled(['scores','playlists','playlist_items','events','announcements','uniforms','incidents'].map(function(t){var filter=t==='scores'?'?select=*&published=eq.true':t==='playlists'&&!S.admin?'?select=*&is_published=eq.true':(t==='events'||t==='announcements'||t==='uniforms')&&!S.admin?'?select=*&published=eq.true':'?select=*';if(t==='incidents'&&!S.admin){if(!S.token)return Promise.resolve([]);filter='?select=*&reporter_id=eq.'+encodeURIComponent(S.userId)}return req(t,filter)}));if(owner!==S.userId)return;var names=['scores','playlists','items','events','announcements','uniforms','incidents'];rows.forEach(function(r,i){if(r.status==='fulfilled'){if(i===0){var m=new Map(S.base.map(function(s){return [s.origin_id,s]}));r.value.forEach(function(x){var y=Object.assign({},x,{language:lang(x.language),pdfUrl:x.pdf_url,origin_id:x.origin_id||'',id:x.id});if(y.origin_id)m.set(y.origin_id,y);else m.set(y.id,y)});S.scores=Array.from(m.values())}else S[names[i]]=r.value}else if(i<6){console.warn(names[i],r.reason)}});if(rows[0].status==='fulfilled'){S.syncState='available';await persistPublic()}else{S.syncState='stale'}}
