function scheduleImmersion(reveal){
 var rd=by('readerRoot').querySelector('.reader');if(!rd)return;clearTimeout(window._coroImmersion);
 if(reveal)rd.classList.remove('immersive');
 if(S.noteTool!=='hand')return;
 window._coroImmersion=setTimeout(function(){if(rd.isConnected&&S.noteTool==='hand'){rd.classList.remove('menu-open');var btn=by('readerMenuButton');if(btn)btn.setAttribute('aria-expanded','false');rd.classList.add('immersive')}},7000)
}
